template <int N>
struct Factorial {
    // Recursive instantiation
    static constexpr int value = N * Factorial<N - 1>::value;
};

// Base case specialization (terminates recursion)
template <>
struct Factorial<0> {
    static constexpr int value = 1;
};

// Computation occurs entirely during compilation.
// Result stored in the type system.
constexpr int result_5 = Factorial<5>::value; // 120

// Note: Requires high compiler recursion limits for large N.

// Alternative using C++17 'if constexpr' (Hybrid TMP/CTCE)
template <int N>
constexpr int factorial_ctce() {
    if constexpr (N <= 1) {
        return 1;
    } else {
        return N * factorial_ctce<N - 1>();
    }
}
constexpr int result_7 = factorial_ctce<7>(); // 5040
